const fs=require('fs'),path=require('path'),crypto=require('crypto'),globby=require('globby'),parser=require('test262-parser');
const root=path.join(path.dirname(require.resolve('test262/package.json')),'test'),src=fs.readFileSync('test/test262.spec.ts','utf8');
const active=[...src.split('const activeCorpus = [')[1].split('\n];')[0].matchAll(/"([^"\n]+\.js)"/g)].map(m=>m[1]);
const globs=[...src.split('const historicalGlobs = [')[1].split('\n];')[0].matchAll(/"([^"\n]+)"/g)].map(m=>m[1]);
const skipped=globby.sync(globs.map(g=>path.join(root,g))).map(f=>path.relative(root,f)).filter(p=>!active.includes(p)).sort();
function row(p){const contents=fs.readFileSync(path.join(root,p),'utf8');return {path:p,sha256:crypto.createHash('sha256').update(contents).digest('hex'),attrs:parser.parseFile({file:p,contents}).attrs};}
const data={activeFiles:active.length,skippedFiles:skipped.length,active:active.map(row),skipped:skipped.map(row)};process.stdout.write(JSON.stringify(data,null,2));
